ALTER TABLE products ADD COLUMN IF NOT EXISTS kind TEXT NOT NULL DEFAULT 'jewellery';
ALTER TABLE products ADD COLUMN IF NOT EXISTS specifications JSONB NOT NULL DEFAULT '{}';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS paypal_order_id TEXT UNIQUE;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS paypal_amount TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS paypal_capture_id TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS coupon_code TEXT;
CREATE TABLE IF NOT EXISTS navigation(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,label TEXT NOT NULL,group_name TEXT NOT NULL,url TEXT NOT NULL,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS wishlists(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS enquiries(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,message TEXT NOT NULL,status TEXT DEFAULT 'new',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS subscribers(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT UNIQUE NOT NULL,active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,author TEXT NOT NULL,rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,active BOOLEAN DEFAULT false);
CREATE TABLE IF NOT EXISTS settings(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,key TEXT UNIQUE NOT NULL,value TEXT NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
